"""Offline art review: native sizes, registered states, real game captures."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'art/concepts/events-trinkets-v1'
cat=json.loads((ROOT/'art/items/trinkets-v1/catalog.json').read_text())
sources=json.loads((ROOT/'art/source/events-trinkets-v1/generation.json').read_text())
data=json.dumps({'catalog':cat,'sources':sources['assets']},ensure_ascii=False)
html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Depths · Finds and forgotten places</title>
<style>
@font-face{font-family:Field;src:url('../../fonts/source-sans-3/SourceSans3-Variable.ttf')}
:root{color-scheme:dark;font-family:Field,system-ui,sans-serif;color:#e6dac1;background:#131a17}*{box-sizing:border-box}body{margin:0;padding:clamp(12px,3vw,36px);max-width:1400px;margin:auto}h1{font-size:clamp(25px,4vw,38px);font-weight:500;margin:0 0 8px}h2{font-weight:500}p{line-height:1.5;color:#b7beac}a{color:#dfba78}button,select,summary{min-height:44px;font:inherit;font-size:17px}button,select{padding:8px 14px;background:#26322b;color:#eadfc5;border:1px solid #56634e;border-radius:4px}button{cursor:pointer}button[aria-selected=true]{border-color:#d4b276;background:#3b4130}button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #d4b276;outline-offset:2px}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}label{display:flex;gap:10px;align-items:center;flex-wrap:wrap}section[hidden]{display:none!important}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:18px}.card{padding:16px;border:1px solid #445040;border-radius:7px;background:#1d2720;min-width:0}.card h2{font-size:21px;margin:10px 0}.sizes{display:flex;align-items:center;justify-content:space-around;gap:8px;min-height:150px}.sizes figure{margin:0;max-width:50%}figcaption{font-size:14px;color:#b7beac;text-align:center;margin:6px 0}img.art{image-rendering:pixelated;object-fit:contain;max-width:100%}.bg{background:#0e1410}.bg[data-bg=stone]{background:#686657}.bg[data-bg=linen]{background:#d2c4a3}.card p{font-size:16px;min-height:46px}details{margin-top:12px;font-size:15px;overflow-wrap:anywhere}summary{cursor:pointer;padding-top:10px;color:#dfba78}pre{white-space:pre-wrap;line-height:1.5;color:#c6cdb9}.prop-layout{display:grid;grid-template-columns:minmax(280px,1fr) minmax(280px,1fr);gap:20px}.compare{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.compare figure{margin:0;text-align:center}.compare img{width:128px;height:128px}.stage{display:flex;align-items:center;justify-content:center;min-height:320px;border:1px solid #52604d;margin:16px 0;padding:12px;position:relative}.stage img{width:384px;max-width:100%;height:auto}.stage.pivot:after{content:'';width:15px;height:15px;border:2px solid #edba5b;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);pointer-events:none}.capture{width:100%;height:auto;border:1px solid #445040}#held{color:#ddc38d}.note{font-size:15px}.sources{margin-top:26px}.intro{max-width:850px}@media(max-width:760px){.prop-layout{grid-template-columns:1fr}.stage{min-height:250px}.sizes{justify-content:flex-start}.card p{min-height:0}}
</style></head><body>
<h1>Finds and forgotten places</h1><p class="intro">Nine worn trinkets and three cave encounters. Compare the small inventory views, then pause and step through each place before and after use.</p>
<nav class="controls" aria-label="Art collections"><button id="items-tab" aria-selected="true">Trinkets</button><button id="props-tab" aria-selected="false">Cave encounters</button><label>Backdrop <select id="background"><option value="dark">Dark</option><option value="stone">Stone</option><option value="linen">Linen</option></select></label></nav>
<section id="items"><div class="grid" id="item-grid"></div><p class="note">Cursed and cleansed versions share the same artwork. The six existing treasure-jewellery designs remain in use.</p><div class="card"><h2>Inside the Pack</h2><div class="controls"><label>Item <select id="pack-item"><option value="bloodstone">Bloodstone</option><option value="shield-bearers-token">Shield-bearer’s token</option><option value="goblin-gold-torc">Goblin gold torc</option></select></label><label>View <select id="pack-size"><option value="phone">Phone</option><option value="desktop">Desktop</option></select></label></div><img class="capture" id="pack-shot" alt="Actual in-game Pack capture"></div></section>
<section id="props" hidden><div class="controls"><label>Place <select id="prop"></select></label><button id="step">Step state</button><button id="play">Play states</button><span id="held" aria-live="polite">Paused · Fresh</span></div><div class="prop-layout"><div class="card"><h2 id="prop-name"></h2><div class="stage bg" id="stage" data-bg="dark"><img class="art" id="held-art" alt="Held encounter state"></div><div class="compare bg" data-bg="dark"><figure><img class="art" id="fresh" alt="Fresh state"><figcaption>Fresh</figcaption></figure><figure><img class="art" id="used" alt="Resolved state"><figcaption>Resolved</figcaption></figure></div><p id="prop-note"></p></div><div class="card"><h2>In the cave</h2><label>View <select id="room-size"><option value="phone">Phone</option><option value="desktop">Desktop</option></select></label><p class="note">The current held state is shown in the real cave renderer.</p><img class="capture" id="room-shot" alt="Actual rendered cave encounter"><p class="note">Resolved means the encounter has been dealt with. It does not promise a particular blessing, healing or reward.</p></div></div></section>
<details class="sources"><summary>Source artwork and exact prompts</summary><p>Made with built-in ImageGen. Original masters are kept byte-for-byte; exports use the existing small-format art contract. The native forked seal is reused on the badge and crate. <a href="../../../docs/events-and-trinkets-art.md">Handoff and rebuild notes</a>.</p><div id="source-list"></div></details>
<script>
const DATA=__DATA__,root='../../../',url=p=>root+p.replace(/^res:\/\//,''),by=id=>document.getElementById(id);
window.reviewState={tab:'items',index:0,playing:false};let timer=null;
for(const item of DATA.catalog.items){const article=document.createElement('article');article.className='card';article.dataset.id=item.id;const h=document.createElement('h2');h.textContent=item.name;article.append(h);const row=document.createElement('div');row.className='sizes bg';row.dataset.bg='dark';for(const size of [128,64,40]){const f=document.createElement('figure'),img=new Image(),caption=document.createElement('figcaption');img.className='art';img.width=size;img.height=size;img.src=url(size===64?item.compact_icon:item.icon);img.alt=item.name+' at '+size+' pixels';caption.textContent=size+' px';f.append(img,caption);row.append(f)}article.append(row);const p=document.createElement('p');p.textContent=item.design;article.append(p);by('item-grid').append(article)}
for(const prop of DATA.catalog.props){const option=document.createElement('option');option.value=prop.id;option.textContent=prop.name;by('prop').append(option)}
for(const source of DATA.sources){const detail=document.createElement('details'),sum=document.createElement('summary'),link=document.createElement('a'),pre=document.createElement('pre');sum.textContent=source.id;link.href=root+source.source;link.textContent='Open original master';pre.textContent=source.prompt;detail.append(sum,link,pre);by('source-list').append(detail)}
function stop(){clearInterval(timer);timer=null;reviewState.playing=false;by('play').textContent='Play states'}
function src(id,value){const i=by(id);if(i.getAttribute('src')!==value)i.src=value;return i}
function ready(i){const expected=i.src;return i.decode().catch(e=>{if(i.src!==expected)return;if(i.complete&&i.naturalWidth>0)return;throw e})}
async function draw(){const p=DATA.catalog.props.find(p=>p.id===by('prop').value),state=reviewState.index===0?'closed':'empty';by('prop-name').textContent=p.name;src('fresh',url(p.textures[0]));src('used',url(p.textures[1]));src('held-art',url(p.textures[reviewState.index]));by('held').textContent=(reviewState.playing?'Playing':'Paused')+' · '+(reviewState.index===0?'Fresh':'Resolved');by('prop-note').textContent=p.mount==='wall'?'Mounted into the cave wall; the original miners’ shrine remains a separate encounter.':p.id==='fouled-well'?'Disturbed water remains murky; this state does not claim it was purified.':'A worked-over crate, with the established stamp and no remaining visible treasure.';src('room-shot',p.id+'-'+state+'-'+by('room-size').value+'.png');window.stateReady=Promise.all([by('fresh'),by('used'),by('held-art'),by('room-shot')].map(ready));await window.stateReady}
function pack(){src('pack-shot','pack-'+by('pack-item').value+'-'+by('pack-size').value+'.png');window.packReady=ready(by('pack-shot'))}
for(const tab of ['items','props'])by(tab+'-tab').onclick=()=>{reviewState.tab=tab;for(const x of ['items','props']){by(x).hidden=x!==tab;by(x+'-tab').setAttribute('aria-selected',String(x===tab))}if(tab==='items')stop();draw()};
by('prop').onchange=()=>{stop();reviewState.index=0;draw()};by('step').onclick=()=>{stop();reviewState.index=1-reviewState.index;draw()};by('play').onclick=()=>{if(reviewState.playing){stop();draw()}else{reviewState.playing=true;by('play').textContent='Pause states';draw();timer=setInterval(()=>{reviewState.index=1-reviewState.index;draw()},1000)}};
by('background').onchange=()=>document.querySelectorAll('.bg').forEach(el=>el.dataset.bg=by('background').value);
by('room-size').onchange=draw;by('pack-size').onchange=pack;by('pack-item').onchange=pack;
window.artReadyPromise=Promise.all([draw(),pack(),...Array.from(document.querySelectorAll('#item-grid img')).map(i=>i.decode())]);
</script></body></html>'''
(OUT/'inspector.html').write_text(html.replace('__DATA__',data),encoding='utf-8')
print('EVENT_TRINKET_INSPECTOR: offline native sizes, held states, sources and actual captures')
